import{a as e}from"./chunk-OOB6KUV2.js";var a={label:"What shipped, and why",body:"The game framing stays, in full. The prestige framing does not. One change carries almost all of it: the main quest is the problem, not the company. Four people on four networks who all have to see the same thing at the same instant \u2014 that is the boss fight, and it is a thing about the work rather than a thing about the logo. The side quests stay exactly as he wrote them, because they are the good part, and the achievements make them literal. Robinson survives as what it is: a hobby line in Off the clock, told as a joke against himself, which is where it is funniest and where it costs nothing.",keeps:["Challenger energy, side quests, achievements, easter eggs \u2014 the whole game layer.","Robinson, demoted from life goal to punchline, which improves it.","The range-not-scatter reframe, which is the genuinely valuable idea in his version."],drops:['"Working at Google is my dream" as the stated motive.',"Any suggestion that the last ten years were a run-up to this.","The claim of completion arriving before the evidence for it."]};var i=50,s=[{k:"TypeScript",v:"strict, no framework, no runtime dependency at all"},{k:"A hand-rolled h()",v:"about twenty lines of DOM helper standing in for a view library"},{k:"A pure reducer",v:"all state in one function, which is why it is unit-tested without a browser"},{k:"esbuild",v:"code splitting per screen, and a gzip budget the CI fails on"},{k:"Plain CSS",v:"one stylesheet, custom properties for the two palettes, container queries for the windows"},{k:"No backend",v:"static files on GitHub Pages. Nothing is uploaded because there is nowhere to upload it"}],o=[{k:"Language",v:"TypeScript, strict, in modules with one job each"},{k:"Runtime dependencies",v:"None. No framework, no bundled library, nothing to audit"},{k:"State",v:"A pure reducer, which is the reason it can be unit-tested without a DOM"},{k:"Size",v:`An initial-load budget of ${i} kB gzip, enforced in CI so it cannot rot`},{k:"Loading",v:"Everything past the first screen is a deferred chunk, fetched only when reached"},{k:"Icons",v:"A ~7 kB subset of Material Symbols, Apache-2.0. Where the subset lacks a glyph, the path is authored and said to be authored"},{k:"Content",v:"One data module. The call view and the plain document view render from it, so they cannot disagree"},{k:"Hosting",v:"Static files from docs/ on GitHub Pages. No server, no build step at request time"}];function d(){return e("div",{class:"bd"},e("p",{class:"bd-lead"},"A CV you can talk to rather than read. It opens as a call because a call is a conversation, and the panels, captions and shared screen carry what a page of bullet points cannot."),e("p",{class:"bd-lead"},"It is also, openly, a demonstration of agentic programming: one person and an agent, one week, with the interface measured off the real product rather than eyeballed. The corrections are in the commit log along with the retractions."),e("h2",{},"Specifications"),e("dl",{class:"bd-rows"},...o.flatMap(t=>[e("dt",{},t.k),e("dd",{},t.v)])),e("h2",{},"What it is built with"),e("ul",{class:"bd-stack"},...s.map(t=>e("li",{},e("b",{},t.k)," \u2014 ",e("span",{},t.v)))),e("h2",{},"What shipped"),e("p",{},a.body))}export{d as a};
